   Um exemplo de Bootstrap


<?php
/**
 * Este arquivo deve estar em APPLICATION_PATH . "/application/" (que foi
 * definido na configuração passada para Yaf_Application) e se chamar
 * Bootstrap.php, para que Yaf_Application possa encontrá-lo.
 */
class Bootstrap extends Yaf_Bootstrap_Abstract {
    public function _initConfig(Yaf_Dispatcher $dispatcher) {
        echo "1st called\n";
    }

    public function _initPlugin(Yaf_Dispatcher $dispatcher) {
        echo "2nd called\n";
    }
}
?>




   Exemplo de Yaf_Application::bootstrap


<?php

defined('APPLICATION_PATH') // APPLICATION_PATH será usado no arquivo de configuração INI
    || define('APPLICATION_PATH', __DIR__);

$application = new Yaf_Application(APPLICATION_PATH . '/conf/application.ini');
$application->bootstrap();
?>


